UPDATE mdl_book_chapters SET content='<h4>Наслаждение живёт в промежутке</h4>
<p>Наслаждение существует не в предмете и не в человеке, а <strong>между нехваткой и наполнением.</strong> Голодный наслаждается едой; сытый той же едой не наслаждается — еда та же, промежутка больше нет.</p>
<div class="kab-figure" style="border: 1px solid #D9E8F2; border-radius: 12px; background: #fff; padding: 12px 12px 10px; margin: 20px 0;">
<a href="https://edu.kabacademy.com/kab/img/schemes/L02-02.webp?v=1" target="_blank" rel="noopener" style="display: block;">
<picture>
<source media="(prefers-reduced-motion: reduce)" srcset="https://edu.kabacademy.com/kab/img/schemes/L02-02-static.png?v=1" width="800" height="429">
<source type="image/webp" srcset="https://edu.kabacademy.com/kab/img/schemes/L02-02.webp?v=1" width="800" height="429">
<img src="https://edu.kabacademy.com/kab/img/schemes/L02-02-static.png?v=1" width="800" height="429" alt="Схема 5. Свет-наслаждение наполняет сосуд — желание наслаждаться; наполнившись, желание гаснет" style="display: block; width: auto; max-width: 100%; height: auto; margin: 0 auto; border-radius: 8px;">
</picture>
</a>
<div style="border-top: 1px solid #EFF7FA; margin-top: 12px; padding-top: 10px; font-size: 13.5px; line-height: 1.6; color: #7A7A7A;"><span style="font-weight: 700; color: #3C5D90;">Схема 5.</span> Наслаждение существует не в предмете и не в человеке, а в промежутке между нехваткой и наполнением. Наполненное желание не уменьшается, а исчезает — вместе с наслаждением, которое давало.</div>
</div>

<h4>Наполненное желание исчезает</h4>
<p>Не уменьшается постепенно, а исчезает — вместе с наслаждением, которое давало.</p>
<p>Проверьте на себе за минуту: вспомните то, чего добивались долго и чего добились. Через сколько это перестало ощущаться?</p>
<div style="border-left:3px solid #4a90a4;background:#f2f8fa;padding:12px 16px;margin:20px 0">
<p style="margin:0"><strong>Клип, 3 мин.</strong> «Погоня за счастьем». «Когда я ожидаю счастье, ожидание даёт ему огромные рамки, а когда получаю его, эти рамки резко сужаются… Счастье — в движении к желаемому.»</p>
<p style="margin:.5em 0 0"><a href="https://kabbalahmedia.info/ru/lessons/cu/Y8OsAcsO" target="_blank" rel="noreferrer">Смотреть</a></p></div>

<h4>Поэтому желания растут</h4>
<p><strong>Чтобы наслаждение было дальше, нужно желание больше предыдущего.</strong> Не потому что человек ненасытен по характеру, а потому что при прежнем размере желания наслаждения не будет вовсе.</p>

<h4>Чем выше качество, тем дольше держится</h4>
<p>Наслаждение от еды измеряется минутами. От покупки — днями. От признания — неделями, иногда месяцами. От понимания чего-то важного — дольше всего.</p>
<p>Кончается на каждой ступени. Меняется только срок.</p>

<h4>Двойное опустошение</h4>
<p>Когда желание встречается с наполнением, ожидается наслаждение — а через некоторое время исчезают оба: и наполнение перестаёт наполнять, и желание перестаёт быть.</p>
<p>Остаётся не нейтральное состояние, а пустота на месте двух вещей сразу. Отсюда знакомая плоскость после достижения, которую обычно списывают на усталость.</p>
<div class="kab-clip" style="border-left: 3px solid #4a90a4; background: #f2f8fa; padding: 12px 16px; margin: 20px 0;">
<video class="nomediaplugin" controls="controls" controlslist="nodownload" preload="metadata" playsinline="playsinline" oncontextmenu="return false;" poster="https://files.kabbalahmedia.info/kabacademy/MAK/Lesson-02-clip-03.jpg" style="display: block; width: 100%; aspect-ratio: 16 / 9; background: #000;"><source src="https://files.kabbalahmedia.info/kabacademy/MAK/Lesson-02-clip-03.mp4" type="video/mp4"></video>
</div>

<h4>Что этим объясняется</h4>
<ul>
<li>Почему достижение цели даёт не радость, а странное ничто.</li>
<li>Почему следующая покупка должна быть дороже предыдущей.</li>
<li>Почему выгорание чаще настигает тех, у кого получается.</li>
</ul>
<p><strong>Вопрос для отклика.</strong> Вспомните желание, которого очень хотели и добились. Что осталось от того наслаждения через полгода?</p>', timemodified=UNIX_TIMESTAMP() WHERE id=2257 AND bookid=962 AND MD5(content)='52395a60f59aa7ad355ba7ae7e8bf19c';
SELECT 2257 item, ROW_COUNT() updated_rows;
UPDATE mdl_book SET timemodified=UNIX_TIMESTAMP() WHERE id=962;
SELECT id, LENGTH(content) len, MD5(content) md5, (LENGTH(content)-LENGTH(REPLACE(content,'/kab/img/schemes/','')))/LENGTH('/kab/img/schemes/') designer_refs FROM mdl_book_chapters WHERE id IN (2258,2257) ORDER BY id;
